-- 本批来源在2026年的全部二十列，预期 24615 行。
SELECT * FROM us_equity_daily WHERE provider='YAHOO' AND trade_date>='2026-01-01' AND trade_date<='2026-10-16' AND symbol IN ('LTSRF', 'LTSSF', 'LTUC', 'LTUM', 'LTUS', 'LUCMF', 'LUCN', 'LUCRF', 'LUDG', 'LUFFF', 'LUGDF', 'LUKEF', 'LUMB', 'LUNMF', 'LUOYF', 'LUVSF', 'LUVU', 'LUXFF', 'LUXMF', 'LVCLF', 'LVGI', 'LVGLF', 'LVMHF', 'LVMUY', 'LVRLF', 'LVSDF', 'LVVV', 'LVWD', 'LVXFF', 'LVZPF', 'LWCL', 'LWCTF', 'LWSCF', 'LXEIF', 'LXENF', 'LXGTF', 'LYBC', 'LYJN', 'LYOPF', 'LYPHF', 'LYRA', 'LYSCF', 'LYSDY', 'LYSFF', 'LYSFY', 'LYTHF', 'LYXX', 'LZAGF', 'LZAGY', 'LZGI', 'LZRFY', 'MAAL', 'MAANF', 'MAARF', 'MABHF', 'MACT', 'MADI', 'MAEOY', 'MAGE', 'MAGMF', 'MAHI', 'MAHLY', 'MAHMF', 'MAHN', 'MAIFF', 'MAJCQ', 'MAJI', 'MAJJ', 'MAKAF', 'MAKSF', 'MAKSY', 'MALDF', 'MALG', 'MALJF', 'MALRF', 'MALRY', 'MAMK', 'MAMTF', 'MANDF', 'MANOF', 'MANVF', 'MANZF', 'MAOFF', 'MAOIF', 'MAOMF', 'MAPGF', 'MAPIF', 'MAPPF', 'MAPS', 'MAQAF', 'MAQCU', 'MARIF', 'MARK', 'MARUF', 'MARUY', 'MARVF', 'MARZF', 'MASN', 'MATAF', 'MATEF', 'MAURY', 'MAUSY', 'MAUTF', 'MAUUF', 'MAWAF', 'MAWHF', 'MAWHY', 'MAXQF', 'MAYNF', 'MAYX', 'MBCI', 'MBCOF', 'MBDC', 'MBFJF', 'MBGAF', 'MBGNF', 'MBGPF', 'MBGYY', 'MBKBF', 'MBKL', 'MBLMF', 'MBLV', 'MBPFF', 'MBPFY', 'MBPG', 'MBQIF', 'MBRFF', 'MBRFY', 'MBSHY') ORDER BY trade_date,symbol,provider LIMIT 100001;

-- 本批明确历史窗口逐来源计数，预期 129 行，合计 371221。
SELECT symbol,provider,count() AS rows FROM us_equity_daily WHERE provider='YAHOO' AND trade_date<='2026-10-16' AND ((trade_date>='2006-01-01' AND symbol IN ('LTSRF', 'LTSSF', 'LTUC', 'LTUM', 'LTUS', 'LUCN', 'LUCRF', 'LUDG', 'LUFFF', 'LUGDF', 'LUKEF', 'LUMB', 'LUNMF', 'LUOYF', 'LUVSF', 'LUVU', 'LUXFF', 'LUXMF', 'LVCLF', 'LVGI', 'LVGLF', 'LVMHF', 'LVMUY', 'LVRLF', 'LVSDF', 'LVWD', 'LVXFF', 'LVZPF', 'LWCL', 'LWSCF', 'LXEIF', 'LXENF', 'LXGTF', 'LYBC', 'LYJN', 'LYOPF', 'LYPHF', 'LYRA', 'LYSCF', 'LYSDY', 'LYSFF', 'LYSFY', 'LYTHF', 'LYXX', 'LZAGF', 'LZAGY', 'LZGI', 'LZRFY', 'MAAL', 'MAANF', 'MAARF', 'MABHF', 'MACT', 'MADI', 'MAEOY', 'MAGE', 'MAGMF', 'MAHI', 'MAHLY', 'MAHMF', 'MAHN', 'MAIFF', 'MAJI', 'MAKAF', 'MAKSF', 'MAKSY', 'MALDF', 'MALG', 'MALJF', 'MALRF', 'MALRY', 'MAMK', 'MAMTF', 'MANDF', 'MANOF', 'MANVF', 'MANZF', 'MAOFF', 'MAOIF', 'MAOMF', 'MAPGF', 'MAPIF', 'MAPPF', 'MAPS', 'MAQAF', 'MAQCU', 'MARIF', 'MARUF', 'MARUY', 'MARVF', 'MASN', 'MATAF', 'MATEF', 'MAURY', 'MAUSY', 'MAUTF', 'MAUUF', 'MAWAF', 'MAWHF', 'MAWHY', 'MAXQF', 'MAYNF', 'MAYX', 'MBCI', 'MBCOF', 'MBDC', 'MBFJF', 'MBGAF', 'MBGNF', 'MBGPF', 'MBGYY', 'MBKBF', 'MBKL', 'MBLMF', 'MBLV', 'MBPFF', 'MBPFY', 'MBPG', 'MBQIF', 'MBRFF', 'MBRFY', 'MBSHY')) OR (trade_date>='2021-10-18' AND symbol IN ('LUCMF', 'LVVV', 'LWCTF', 'MAJCQ', 'MAJJ', 'MARK', 'MARZF'))) GROUP BY symbol,provider ORDER BY symbol,provider LIMIT 100001;

-- 本批7个独立五年段，预期8785行；原全历史任务保留待核或失败。
SELECT * FROM us_equity_daily WHERE provider='YAHOO' AND trade_date>='2021-10-18' AND trade_date<='2026-10-16' AND symbol IN ('LUCMF', 'LVVV', 'LWCTF', 'MAJCQ', 'MAJJ', 'MARK', 'MARZF') ORDER BY trade_date,symbol,provider LIMIT 100001;

-- 结合原文、Native与全部键值证明；WAL不独立代表完成。
SELECT name,writerTxn,sequencerTxn,bufferedTxnSize,suspended FROM wal_tables() WHERE name IN ('us_equity_daily','us_equity_intraday') ORDER BY name;
